const pendingRenderBase=render;
render=function(){pendingInit();pendingRenderBase();document.querySelectorAll('[data-ten=config],.ten-config').forEach(x=>x.remove());if(ten.role==='super'){
 const anchor=document.querySelector('.side-scroll');anchor?.insertAdjacentHTML('beforeend',`<button class="side-link" data-pending="cleanup-page">${icon('shield')}<span>${T('Penyesuaian Data Label','Label Data Updates')}</span></button>`);
 if(ten.role==='super'&&state.page==='dashboard'&&state.mode==='platform'){const insight=document.querySelector('.insight7');if(insight&&(ten.achievementNews.length||ten.bonuses.some(b=>b.status==='claimed')))insight.innerHTML=newsPending();}
 }document.querySelectorAll('.payout-card-ui h3').forEach(h=>h.textContent=directoryBankDisplay(h.textContent));};
